std::string s = "Base";

// Overload 1: Appending a C-style string literal
s.append(" Extension");

// Overload 2: Appending a count of a specific character
s.append(3, '!');

// Overload 3: Appending a substring (pos, count)
std::string source = "IgnorePartData";
s.append(source, 10, 4); // Appends "Data"

// Final s: "Base Extension!!!Data"

std::vector<int> v = {10, 20};

// Overload 4 (std::vector): Insert N copies
v.insert(v.begin() + 1, 2, 99);

// Overload 5 (std::vector): Insert a range
int arr[] = {30, 40};
v.insert(v.end(), std::begin(arr), std::end(arr));
// Final v: {10, 99, 99, 20, 30, 40}
